installation:
// Maven Repository
<repository>
    <id>dynomakeRepository</id>
    <url>https://maven.dynomake.it/releases</url>
</repository>

// Maven Dependency
<dependency>
    <groupId>space.dynomake</groupId>
    <artifactId>libretranslate-java</artifactId>
    <version>1.0.9</version>
</dependency>

// Gradle Repository
repositories {
    maven {
        name = 'dynomakeRepository'
        url = uri('https://maven.dynomake.it/releases')
    }
}

// Gradle Dependency
implementation 'space.dynomake:libretranslate-java:1.0.9'

usage:
// Configure API settings (optional)
Translator.setUrlApi("https://translate.example.com/translate");
Translator.setApiKey("your_api_key");

// Translate text
String translated = Translator.translate(Language.ENGLISH, Language.GERMAN, "Hello, World!");
System.out.println(translated); // "Hallo, Welt!"
